files.main.css:
/* skills/notebook/assets/science/common.css */
.science {
  --ink:#191a20;
  --muted:#646772;
  --blue:#4263eb;
  --teal:#4263eb;
  --orange:#ec704a;
  --paper:#fff;
  max-width: 1100px;
  margin: auto;
  padding: 36px 40px 24px;
  background: var(--paper);
  color: var(--ink);
  font:
    18px/1.55 -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    sans-serif;
  -webkit-font-smoothing: antialiased;
}
.science * {
  box-sizing: border-box;
}
.science header {
  margin-bottom: 12px;
}
.science h1 {
  font-size: 32px;
  line-height: 1.18;
  letter-spacing: -.035em;
  font-weight: 600;
  margin: 0 0 10px;
}
.science header p {
  font-size: 20px;
  max-width: 760px;
  margin: 0;
  color: var(--muted);
}
.science h2 {
  font-size: 20px;
  font-weight: 500;
  margin: 16px 0;
}
.science figure {
  margin: 0;
  min-width: 0;
}
.science svg {
  width: 100%;
  height: auto;
  display: block;
  overflow: hidden;
}
.science svg text {
  font-family: inherit;
  font-size: 22px;
  fill: var(--ink);
}
.science svg .axis-label {
  font-size: 20px;
  fill: var(--muted);
}
.science .grid {
  stroke: #e8e9ed;
  stroke-width: 1;
  fill: none;
}
.science .axis {
  stroke: #b7bac4;
  stroke-width: 1.2;
  fill: none;
}
.science .curve {
  stroke: var(--blue);
  stroke-width: 3;
  fill: none;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.science .teal {
  stroke: var(--blue);
  fill: none;
  stroke-width: 3;
}
.science .orange {
  stroke: var(--orange);
  fill: none;
  stroke-width: 3;
}
.science .dot {
  fill: var(--orange);
  stroke: var(--paper);
  stroke-width: 2;
}
.science .equation {
  font: 24px/1.6 Georgia, serif;
  overflow-wrap: anywhere;
}
.science .readout {
  font-variant-numeric: tabular-nums;
  color: var(--muted);
  font-size: 18px;
}
.science .insight {
  font-size: 24px;
  font-weight: 450;
  letter-spacing: -.02em;
  text-align: center;
  margin: 0 auto 20px;
  max-width: 800px;
}
.science .controls {
  display: flex;
  justify-content: center;
  flex-wrap: wrap;
  align-items: center;
  gap: 16px 24px;
  margin: 20px auto 24px;
  max-width: 660px;
}
.science button,
.science select,
.science input[type=number] {
  font: inherit;
  color: var(--ink);
  border: 1px solid #d8dae0;
  border-radius: 9px;
  background: transparent;
  min-height: 44px;
  padding: 8px 16px;
}
.science button {
  cursor: pointer;
  transition: background .15s;
}
.science button:hover {
  background: #f1f2f5;
}
.science button.primary {
  background: #202127;
  border-color: #202127;
  color: #fff;
  min-width: 92px;
}
.science button.primary:hover {
  background: #3d3f48;
}
.science button:disabled {
  opacity: .35;
  cursor: default;
}
.science :focus-visible {
  outline: 3px solid #8a9cf5;
  outline-offset: 4px;
}
.science .control {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 6px 14px;
  flex: 1 1 200px;
  min-width: 0;
  font-size: 18px;
}
.science .control input {
  grid-column: 1/-1;
  width: 100%;
  margin: 0;
  min-height: 36px;
  accent-color: #30323c;
}
.science .scrubber {
  flex: 1 1 240px;
  max-width: 360px;
  accent-color: #30323c;
  min-height: 44px;
}
.science output {
  font-variant-numeric: tabular-nums;
}
.science .legend {
  display: flex;
  justify-content: center;
  flex-wrap: wrap;
  gap: 10px 24px;
  font-size: 18px;
  color: var(--muted);
  margin: 12px 0 24px;
}
.science .legend span:before {
  content: "";
  display: inline-block;
  width: 16px;
  height: 3px;
  background: var(--blue);
  vertical-align: middle;
  margin-right: 8px;
}
.science .legend .warm:before {
  background: var(--orange);
}
.science .legend .green:before {
  background: var(--blue);
}
.science .note {
  font-size: 18px;
  color: var(--muted);
  margin: 16px 0;
}
.science .source {
  font-size: 16px;
  color: var(--muted);
  margin-top: 20px;
}
.science a {
  color: inherit;
  text-underline-offset: 4px;
}
.science details {
  margin: 28px 0 0;
  border-top: 1px solid #e8e9ee;
  padding-top: 16px;
}
.science summary {
  cursor: pointer;
  font-size: 18px;
  color: var(--muted);
  width: fit-content;
  min-height: 44px;
}
.science details[open] summary {
  color: var(--ink);
}
.science details .controls {
  justify-content: flex-start;
  max-width: none;
  margin: 12px 0;
  gap: 20px 32px;
}
.science details .control {
  max-width: 360px;
}
.science .matrix {
  display: grid;
  gap: 6px;
  margin: 10px auto;
  max-width: 240px;
}
.science .matrix input,
.science .matrix button {
  width: 100%;
  min-width: 0;
  text-align: center;
  padding: 4px;
  font-variant-numeric: tabular-nums;
  border: 0;
  border-radius: 0;
  font-size: 26px;
}
.science .matrix input.active {
  color: var(--blue);
  background: #eef1ff;
}
.science .matrix button[aria-pressed=true] {
  color: var(--blue);
  background: #eef1ff;
  border-radius: 6px;
}
.science .matrix-grid {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 32px;
  max-width: 780px;
  margin: 4px auto 20px;
}
.science .matrix-grid h2 {
  text-align: center;
}
.science .matrix-grid .matrix {
  position: relative;
  padding: 0 8px;
  border-left: 2px solid #b8bbc6;
  border-right: 2px solid #b8bbc6;
}
.science .stats {
  font-size: 26px;
  margin: 4px 0 12px;
}
.science .equation-box {
  padding: 12px 0;
  text-align: center;
}
.science .inline {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
}
.science .inline input[type=number] {
  width: 85px;
}
.science .touch {
  touch-action: none;
  cursor: crosshair;
}
.science .summary {
  font-size: 20px;
  margin: 8px auto;
  text-align: center;
  max-width: 800px;
}
.science .quiet {
  border: 0;
  color: var(--muted);
  font-size: 18px;
}
.science .two-plots {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 32px;
}
.science .explain-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 32px;
  align-items: center;
}
.science .compact-plot {
  max-width: 480px;
  margin: auto;
}
.science .keyboard-help {
  font-size: 18px;
  color: var(--muted);
}
.science.linear {
  --paper:#111318;
  --ink:#e9edf4;
  --muted:#a6adba;
  --blue:#70acff;
  --orange:#ffc565;
  background: var(--paper);
}
.science.linear h1 {
  font-weight: 500;
}
.science.linear .grid {
  stroke: #272e3a;
}
.science.linear .control input,
.science.linear .scrubber {
  accent-color: #d1daec;
}
.science.linear button {
  border-color: #414856;
}
.science.linear button:hover {
  background: #292e39;
}
.science.linear button.primary {
  background: #e6eaf2;
  color: #15171d;
  border-color: #e6eaf2;
}
.science.linear details {
  border-color: #303641;
}
.science.linear .matrix input {
  color: #e9edf4;
}
.science.linear .matrix {
  border-left: 2px solid #737f93;
  border-right: 2px solid #737f93;
}
.science.linear select {
  background: #111318;
}
.science.linear .preset-bar {
  display: flex;
  justify-content: center;
  flex-wrap: wrap;
  gap: 8px;
}
.science.linear .preset-bar button {
  border: 0;
  font-size: 18px;
}
.science.linear .preset-bar button[aria-pressed=true] {
  background: #2a3140;
  color: #fff;
}
@media (max-width: 700px) {
  .science {
    padding: 24px 18px;
  }
  .science h1 {
    font-size: 28px;
  }
  .science header p {
    font-size: 18px;
  }
  .science .insight {
    font-size: 21px;
  }
  .science .controls {
    gap: 12px;
  }
  .science .two-plots,
  .science .explain-grid {
    grid-template-columns: 1fr;
    gap: 16px;
  }
  .science .matrix-grid {
    gap: 16px;
  }
  .science .matrix input,
  .science .matrix button {
    font-size: 20px;
  }
  .science .equation {
    font-size: 21px;
  }
  .science .matrix-grid h2 {
    font-size: 18px;
  }
  .science .legend {
    font-size: 16px;
  }
  .science svg {
    min-height: 220px;
  }
  .science details .controls {
    display: grid;
    grid-template-columns: 1fr;
  }
  .science .control {
    width: 100%;
  }
  .science.linear .preset-bar {
    gap: 0;
  }
  .science.linear .preset-bar button {
    padding: 8px 10px;
    font-size: 16px;
  }
}
.science .map-figure {
  max-width: 800px;
  margin: auto;
}
.science.tensor {
  --blue:#6658d9;
}
.science .keyboard-cursor {
  opacity: 0;
}
.science svg:focus-visible .keyboard-cursor {
  opacity: 1;
}
@media (max-width: 700px) {
  .science svg .axis-label {
    font-size: 26px;
  }
  .science.sound svg .axis-label,
  .science.gaussian svg .axis-label {
    font-size: 34px;
  }
}
.science .touch:focus:not(:focus-visible),
.science .touch[data-pointer-focus] {
  outline: none;
}

/* skills/notebook/assets/science/wave/style.css */
html,
body {
  height: 100%;
  overflow: hidden;
}
.wave {
  height: 100%;
  overflow: auto;
  overscroll-behavior: contain;
  padding-top: 26px;
}
.wave header p {
  font-size: 17px;
  max-width: 700px;
}
.wave nav {
  display: flex;
  gap: 8px;
  margin: 20px 0;
}
.wave nav button {
  border: 0;
  border-radius: 0;
  border-bottom: 2px solid transparent;
  padding: 6px 10px;
  font-size: 15px;
  color: var(--muted);
}
.wave nav button[aria-pressed=true] {
  border-color: var(--ink);
  color: var(--ink);
}
.experiment {
  display: grid;
  grid-template-columns: minmax(220px, 1.25fr) minmax(210px, 1fr);
  gap: 26px;
  align-items: start;
}
.wave .field-view {
  position: relative;
  line-height: 0;
  border: 1px solid #aab0bf;
}
.wave #wave-field {
  display: block;
  width: 100%;
  aspect-ratio: 1;
}
.wave .dimension {
  position: absolute;
  top: 8px;
  left: 9px;
  font-size: 13px;
  line-height: 1.3;
  color: #353b49;
  background: #f3f4f8b0;
}
.wave .scale {
  display: flex;
  align-items: center;
  gap: 9px;
  font-size: 13px;
  color: var(--muted);
  margin: 10px 0;
}
.wave .scale i {
  height: 8px;
  flex: 1;
  background:
    linear-gradient(
      90deg,
      #2d55a2,
      #f3f4f8,
      #c94f2f);
}
.wave .parameters {
  display: grid;
  gap: 18px;
}
.wave .control {
  font-size: 15px;
}
.wave output {
  color: var(--muted);
}
.wave button,
.wave select,
.wave input[type=number] {
  font-size: 14px;
}
.wave .shapes {
  display: flex;
  gap: 4px;
}
.wave .shapes button {
  padding: 8px;
  border: 0;
  border-radius: 0;
  border-bottom: 2px solid transparent;
  color: var(--muted);
}
.wave .shapes button[aria-pressed=true] {
  border-color: var(--blue);
  color: var(--ink);
}
.wave .seed {
  font-size: 14px;
  color: var(--muted);
}
.wave .seed input {
  width: 100px;
  margin-left: 10px;
}
.wave .actions {
  display: flex;
  gap: 8px;
}
.wave progress {
  width: 100%;
  height: 5px;
  accent-color: #4967b5;
}
.wave #status {
  font-size: 14px;
  line-height: 1.45;
  color: var(--muted);
  margin: 0;
  min-height: 42px;
}
.wave .note {
  font-size: 14px;
}
.wave #result-caption {
  min-height: 44px;
}
.wave #wave-cut {
  display: block;
  width: 100%;
  height: 120px;
}
.wave .equation {
  font-size: 21px;
}
.wave #failure,
.wave #media-error {
  font-size: 14px;
  color: #ad3422;
  margin: 0;
}
.wave [hidden] {
  display: none !important;
}
.wave video {
  display: block;
  width: 100%;
  max-height: 530px;
  background: #f3f4f8;
}
.wave .media-controls {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
  font-size: 14px;
  margin: 15px 0;
}
.wave .media-controls input {
  accent-color: var(--blue);
}
.wave details p {
  font-size: 15px;
}
@media (max-width: 580px) {
  .wave {
    padding: 20px 16px;
  }
  .wave h1 {
    font-size: 27px;
  }
  .experiment {
    grid-template-columns: 1fr;
    gap: 16px;
  }
  .wave .field-view {
    max-width: 380px;
    margin: auto;
  }
  .wave .parameters {
    grid-template-columns: 1fr 1fr;
    gap: 14px;
  }
  .wave .parameters .shapes,
  .wave .parameters .actions,
  .wave progress,
  .wave #status,
  .wave #failure {
    grid-column: 1/-1;
  }
  .wave .seed {
    grid-column: 1/-1;
  }
  .wave .equation {
    font-size: 18px;
  }
}
@media (prefers-color-scheme: dark) {
  .wave {
    --paper:#17191f;
    --ink:#e5e8ef;
    --muted:#a9afbd;
    color-scheme: dark;
  }
  .wave button,
  .wave select,
  .wave input[type=number] {
    border-color: #565d6b;
  }
  .wave button:hover {
    background: #30343e;
  }
  .wave details {
    border-color: #414753;
  }
  .wave #failure,
  .wave #media-error {
    color: #ffad9e;
  }
}
.wave .section-line {
  position: absolute;
  left: 0;
  right: 0;
  top: 50%;
  border-top: 1px dashed #6b7590a0;
  pointer-events: none;
}
.wave #probe-marker {
  position: absolute;
  width: 14px;
  height: 14px;
  box-sizing: border-box;
  border: 2px solid #202229;
  border-radius: 50%;
  box-shadow: 0 0 0 2px #ffffffdf;
  transform: translate(-50%, -50%);
  pointer-events: none;
}
