import {
  Wave,
  parameters,
  size
} from "./chunk-2OH4HRIX.js";

// skills/notebook/assets/science/wave/solver.ts
var scope = self;
var wave;
var id = 0;
var timer = 0;
var spare;
var lastSent = 0;
var finished = false;
function publish() {
  if (!wave || !spare || finished) return;
  const now = performance.now(), done = wave.step === wave.steps;
  if (!done && now - lastSent < 40) return;
  new Float32Array(spare).set(wave.field);
  const frame = { id, step: wave.step, total: wave.steps, done, buffer: spare, report: wave.report() };
  scope.postMessage(frame, [spare]);
  spare = void 0;
